// ═══════════════════════════════════════════════════════════════
// BROWSER TASK BUILDER v2
// ═══════════════════════════════════════════════════════════════

const input = $input.first().json;
const userRequest = String(input.query || input.user_request || input.message || input.text || JSON.stringify(input));

console.log('[Browser] Raw input:', JSON.stringify(input));
console.log('[Browser] User request:', userRequest);

const request = String(userRequest).toLowerCase();
let task = '';

// ═══════════════════════════════════════════════════════════════
// SHOPPING
// ═══════════════════════════════════════════════════════════════
if (request.includes('shop') || request.includes('buy') || request.includes('order') ||
    request.includes('blinkit') || request.includes('swiggy') || request.includes('zepto') ||
    request.includes('amazon') || request.includes('cart') || request.includes('flipkart')) {

  // ── Product extraction ───────────────────────────────────────
  // Stop at "to cart", "to my cart", "from [store]", "on [store]"
  // NOT just "to" — that breaks "500 grams of tomatoes TO cart"
  const stores = 'blinkit|amazon|zepto|swiggy|instamart|flipkart|myntra|meesho|bigbasket';
  const stopPattern = new RegExp(
    `\\s+(?:to\\s+(?:my\\s+)?(?:${stores})(?:\\s+cart)?|to\\s+(?:my\\s+)?cart|from\\s+(?:${stores})|on\\s+(?:${stores})|in\\s+(?:${stores}))`,
    'i'
  );

  // Extract verb + everything after, then cut at stop pattern
  const verbMatch = userRequest.match(
    /(?:order|buy|get|find|shop\s+for|add)\s+(?:some\s+)?(.+)/i
  );

  let product = userRequest; // fallback
  if (verbMatch) {
    product = verbMatch[1].replace(stopPattern, '').trim();
  }

  const encodedProduct = encodeURIComponent(product);

  // ── Cart intent ──────────────────────────────────────────────
  const wantsCart = request.includes('add') || request.includes('cart') ||
                    request.includes('order') || request.includes('buy');
  const cartInstruction = wantsCart
    ? `Click on the first relevant result, then click "Add to Cart". Stop before checkout. Report the product name, price, and confirm it was added to cart.`
    : `Find the first relevant result and report its name and price only. Do not add to cart.`;

  // ── Route to store ───────────────────────────────────────────
  if (request.includes('blinkit')) {
    task = `Go to https://blinkit.com/s/?q=${encodedProduct} — direct search for "${product}" on Blinkit. Wait for products to load. Find the first relevant product, click ADD. Stop before checkout. Report what was added and its price.`;
  } else if (request.includes('zepto')) {
    task = `Go to https://www.zeptonow.com/search?query=${encodedProduct} — direct search for "${product}" on Zepto. Wait for results. Add the first item to cart. Stop before checkout. Report what was added and price.`;
  } else if (request.includes('amazon')) {
    task = `Go to https://www.amazon.in/s?k=${encodedProduct} — direct search for "${product}" on Amazon India. ${cartInstruction}`;
  } else if (request.includes('swiggy') || request.includes('instamart')) {
    task = `Go to https://www.swiggy.com/instamart/search?query=${encodedProduct} — direct search for "${product}" on Swiggy Instamart. Wait for results. ${cartInstruction}`;
  } else if (request.includes('flipkart')) {
    task = `Go to https://www.flipkart.com/search?q=${encodedProduct} — direct search for "${product}" on Flipkart. ${cartInstruction}`;
  } else {
    task = `${userRequest}. Stop before final checkout/payment. Confirm what was added to cart and its price.`;
  }
}

// ═══════════════════════════════════════════════════════════════
// SOCIAL MEDIA
// ═══════════════════════════════════════════════════════════════
else if (request.includes('like') || request.includes('tweet') || request.includes('post') ||
         request.includes('follow') || request.includes('x.com') || request.includes('twitter') ||
         request.includes('instagram') || request.includes('linkedin')) {
  task = `${userRequest}. Confirm the action was completed successfully and report what you did.`;
}

// ═══════════════════════════════════════════════════════════════
// BOOKING
// ═══════════════════════════════════════════════════════════════
else if (request.includes('book') || request.includes('reserve') || request.includes('restaurant') ||
         request.includes('hotel') || request.includes('flight') || request.includes('ticket') ||
         request.includes('zomato') || request.includes('makemytrip')) {
  task = `${userRequest}. Stop before final payment. Confirm what was booked/selected.`;
}

// ═══════════════════════════════════════════════════════════════
// YOUTUBE
// ═══════════════════════════════════════════════════════════════
else if (request.includes('youtube') || (request.includes('video') && !request.includes('blinkit'))) {
  let query = userRequest;
  const onYt  = userRequest.match(/(?:play|search|find|watch)\s+(.+?)\s+(?:on\s+youtube|on\s+yt)/i);
  const ytFor = userRequest.match(/youtube\s+(?:for|on|about)?\s*(.+)/i);
  const playX = userRequest.match(/(?:play|search for|watch)\s+(.+)/i);
  if (onYt)  query = onYt[1].trim();
  else if (ytFor && ytFor[1].trim()) query = ytFor[1].trim();
  else if (playX) query = playX[1].replace(/on youtube|on yt/gi, '').trim();
  task = `Go to https://www.youtube.com/results?search_query=${encodeURIComponent(query)} — direct YouTube search for "${query}". Wait for results. Click the first relevant video and start playing it. Report which video you opened.`;
}

// ═══════════════════════════════════════════════════════════════
// GOOGLE SEARCH
// ═══════════════════════════════════════════════════════════════
else if (request.includes('google') || request.includes('search') || request.includes('find') ||
         request.includes('look up') || request.includes('research')) {
  let query = userRequest;
  const m = userRequest.match(/(?:google|search|find|look up|research)\s+(?:for|about)?\s*(.+)/i);
  if (m) query = m[1].trim();
  task = `Go to https://google.com, search for "${query}", read the top 3 results and summarize what you found.`;
}

// ═══════════════════════════════════════════════════════════════
// OPEN URL
// ═══════════════════════════════════════════════════════════════
else if (request.includes('go to') || request.includes('open') || request.includes('visit') ||
         request.match(/[a-z0-9-]+\.(com|org|net|io|dev)/i)) {
  task = `${userRequest}. Wait for the page to fully load and report what you see.`;
}

// ═══════════════════════════════════════════════════════════════
// DEFAULT
// ═══════════════════════════════════════════════════════════════
else {
  task = `${userRequest}. Report what you did and the result.`;
}

console.log('[Browser] Task built:', task);
return { task, original_request: userRequest };

/*
FIX SUMMARY — product extraction:

OLD (broken):
  regex stops at any "to" → "Add 500 grams of tomatoes TO cart" → extracts "500 grams of"

NEW (fixed):
  regex stops only at "to cart", "to my cart", "from blinkit", "on blinkit" etc.
  → "Add 500 grams of tomatoes to cart on Blinkit" → extracts "500 grams of tomatoes" ✅
  → "Add Razer mouse to cart on Amazon" → extracts "Razer mouse" ✅
  → "Order milk from Blinkit" → extracts "milk" ✅
*/

// Format the response back to main Arya agent
const input = $input.first().json;

console.log('[Browser] Raw response:', JSON.stringify(input));

let response;

if (input.success) {
  response = input.result || 'Browser task completed successfully.';
} else {
  response = `Browser task failed: ${input.result || 'Unknown error'}`;
}

console.log('[Browser] Final response:', response);

return { result: response };
